7'),(183,'admin@rmutt.local','create_event','match','9','{\"id\":\"10\",\"match_id\":\"9\",\"event_type\":\"yellow_card\",\"team_id\":\"18\",\"student_id\":\"71\",\"period_number\":\"2\",\"elapsed_seconds\":\"3180\",\"added_time\":\"0\",\"points\":\"0\",\"card_type\":\"yellow\",\"note\":\"ใบเหลืองจากการเข้าสกัดหนัก\",\"metadata_json\":\"[]\",\"is_voided\":\"0\",\"created_by\":\"admin@rmutt.local\",\"created_at\":\"2026-10-05 18:37:27\",\"voided_by\":null,\"voided_at\":null}','2026-10-05 18:37:27'),(184,'admin@rmutt.local','create','news','2','{\"id\":\"2\",\"title\":\"ฟุตบอลปิดฉากเดือด ฟุตบอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A ชนะ 3-1\",\"slug\":\"football-final-demo-37380\",\"excerpt\":\"ผลการแข่งขันฟุตบอลรอบชิงชนะเลิศถูกบันทึกครบถ้วน พร้อมตารางคะแนนและเหตุการณ์สำคัญในระบบ\",\"body\":\"การแข่งขันฟุตบอลในทัวร์นาเมนต์กีฬาสี RMUTT Sport Demo 2569 จบลงด้วยสกอร์ 3-1 ระบบได้บันทึกผลการแข่งขัน เหตุการณ์สำคัญ รายชื่อนักกีฬา และตารางคะแนนไว้ครบถ้วน เพื่อใช้ประชาสัมพันธ์และจัดทำรายงานผู้บริหารต่อไป\",\"cover_image_url\":\"/public/assets/court.jpg\",\"news_type\":\"general\",\"department_code\":null,\"status\":\"published\",\"is_pinned\":\"1\",\"published_at\":\"2026-10-16 18:00:00\",\"author_email\":\"admin@rmutt.local\",\"created_at\":\"2026-10-05 18:37:27\",\"updated_at\":\"2026-10-05 18:37:27\"}','2026-10-05 18:37:27'),(185,'admin@rmutt.local','create','news','3','{\"id\":\"3\",\"title\":\"สรุปภาพรวมทัวร์นาเมนต์ครบ 9 กีฬา\",\"slug\":\"all-sports-summary-demo-37380\",\"excerpt\":\"ทุกชนิดกีฬาถูกตั้งค่า สร้างทีม บันทึกนักกีฬา ตารางแข่งขัน และผลการแข่งขันเรียบร้อย\",\"body\":\"ระบบจำลองข้อมูลครบทั้ง เซปักตะกร้อ, เปตอง, เทเบิลเทนนิส, แบดมินตัน, บาสเกตบอล, ฟุตซอล, วิ่ง 100 เมตร, วอลเลย์บอล, ฟุตบอล พร้อมข่าว ประวัตินักกีฬา และรายงานผลการแข่งขัน\",\"cover_image_url\":\"/public/assets/court.jpg\",\"news_type\":\"general\",\"department_code\":null,\"status\":\"published\",\"is_pinned\":\"0\",\"published_at\":\"2026-10-16 19:00:00\",\"author_email\":\"admin@rmutt.loc