INSERT INTO `news` VALUES (1,'เปิดระบบ RMUTT Sports MVP','welcome','ระบบจัดการกีฬาเวอร์ชันทดลองพร้อมใช้งานแล้ว','ทีมงานสามารถเริ่มเพิ่มกีฬา ตารางแข่งขัน ผลการแข่งขัน และประกาศได้จากหน้า Dashboard','','general',NULL,'published',1,'2026-10-05 11:25:43','','2026-10-05 11:25:43','2026-10-05 11:25:43',NULL),(2,'ฟุตบอลปิดฉากเดือด ฟุตบอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A ชนะ 3-1','football-final-demo-37380','ผลการแข่งขันฟุตบอลรอบชิงชนะเลิศถูกบันทึกครบถ้วน พร้อมตารางคะแนนและเหตุการณ์สำคัญในระบบ','การแข่งขันฟุตบอลในทัวร์นาเมนต์กีฬาสี RMUTT Sport Demo 2569 จบลงด้วยสกอร์ 3-1 ระบบได้บันทึกผลการแข่งขัน เหตุการณ์สำคัญ รายชื่อนักกีฬา และตารางคะแนนไว้ครบถ้วน เพื่อใช้ประชาสัมพันธ์และจัดทำรายงานผู้บริหารต่อไป','public/assets/court.jpg','general',NULL,'published',1,'2026-10-16 18:00:00','admin@rmutt.local','2026-10-05 18:37:27','2026-10-05 18:37:27',NULL),(3,'สรุปภาพรวมทัวร์นาเมนต์ครบ 9 กีฬา','all-sports-summary-demo-37380','ทุกชนิดกีฬาถูกตั้งค่า สร้างทีม บันทึกนักกีฬา ตารางแข่งขัน และผลการแข่งขันเรียบร้อย','ระบบจำลองข้อมูลครบทั้ง เซปักตะกร้อ, เปตอง, เทเบิลเทนนิส, แบดมินตัน, บาสเกตบอล, ฟุตซอล, วิ่ง 100 เมตร, วอลเลย์บอล, ฟุตบอล พร้อมข่าว ประวัตินักกีฬา และรายงานผลการแข่งขัน','public/assets/court.jpg','general',NULL,'published',0,'2026-10-16 19:00:00','admin@rmutt.local','2026-10-05 18:37:27','2026-10-05 18:37:27',NULL),(4,'Hall of Fame: นักฟุตบอลยอดเยี่ยมประจำทัวร์นาเมนต์','hall-football-demo-37380','ยกย่องนักกีฬาที่ทำผลงานโดดเด่นในรอบชิงชนะเลิศฟุตบอล','นักกีฬาตัวอย่างจากทีมชนะเลิศได้รับการบันทึกใน Hall of Fame เพื่อแสดงบนหน้าเว็บสาธารณะ','public/assets/court.jpg','hall_of_fame',NULL,'published',1,'2026-10-16 20:00:00','admin@rmutt.local','2026-10-05 18:37:27','2026-10-05 18:37:27',NULL),(5,'เต็มพลัง! เตรียมเชียร์ ฟุตซอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A พบ ฟุตซอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B ในการแข่งขันฟุตซอล','เต็มพลัง-เตรียมเชียร์-ฟุตซอล-สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ-a-พบ-ฟุตซอล-สาขาวิชาวิศวกรรมคอมพิวเตอร์-b-ในการแข่งขันฟุตซอล','สรุปการแข่งขัน T1-M10 | ฟุตซอล | กีฬาสี RMUTT Sport Demo 2569 - ทุกกีฬา (37380) | ฟุตซอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A พบ ฟุตซอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | ยังไม่บันทึกผล','การแข่งขันรายการ กีฬาสี RMUTT Sport Demo 2569 - ทุกกีฬา (37380) ฟุตซอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A พบ ฟุตซอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B กำหนดแข่งขัน 2026-10-15T18:39 ณ  ทีมงานจะประกาศรายละเอียดเพิ่มเติมผ่านเว็บไซต์ประชาสัมพันธ์กีฬา','/prsport/public/uploads/news/banner-1791805210189-1791805210-f826c9.png','general',NULL,'published',1,'2026-10-12 18:40:23','admin@rmutt.local','2026-10-12 18:40:23','2026-10-12 18:40:23',''),(6,'เต็มพลัง! สรุปผล ฟุตบอล: ฟุตบอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B พบ ฟุตบอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A','เต็มพลัง-สรุปผล-ฟุตบอล-ฟุตบอล-สาขาวิชาวิศวกรรมคอมพิวเตอร์-b-พบ-ฟุตบอล-สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ-a','สรุปการแข่งขัน T1-M13 | ฟุตบอล | กีฬาสี RMUTT Sport Demo 2569 - ทุกกีฬา (37380) | ฟุตบอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B พบ ฟุตบอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A | 5 - 1','การแข่งขันรายการ กีฬาสี RMUTT Sport Demo 2569 - ทุกกีฬา (37380) ฟุตบอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B พบ ฟุตบอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A ผลการแข่งขัน 5 - 1 ณ  ทีมงานจะประกาศรายละเอียดเพิ่มเติมผ่านเว็บไซต์ประชาสัมพันธ์กีฬา','','general',NULL,'draft',0,'','admin@rmutt.local','2026-10-16 23:56:27','2026-10-16 23:56:27','');
