INSERT INTO `report_categories` VALUES (1,'competition','รายงานประชาสัมพันธ์ผลการแข่งขันกีฬา','เรียบเรียงผลการแข่งขัน รางวัล และประเด็นเผยแพร่ข่าวกีฬา','trophy',10,1),(2,'project','รายงานประชาสัมพันธ์โครงการ/กิจกรรมกีฬา','สรุปการจัดโครงการ กิจกรรมกีฬา และสาระสำหรับเผยแพร่','clipboard-check',20,1),(3,'performance','รายงานภาพรวมงานประชาสัมพันธ์กีฬา','สรุปภาพรวมการสื่อสาร ข่าวสาร และการดำเนินงานประชาสัมพันธ์กีฬา','file-chart-column',30,1),(4,'kpi','รายงานตัวชี้วัดงานประชาสัมพันธ์กีฬา','เปรียบเทียบเป้าหมาย ผลจริง และความสำเร็จของงานสื่อสารกีฬา','gauge',40,1),(5,'executive','รายงานสรุปประชาสัมพันธ์กีฬาสำหรับผู้บริหาร','สรุปสาระสำคัญด้านประชาสัมพันธ์กีฬาเพื่อประกอบการตัดสินใจ','briefcase-business',50,1),(6,'budget','รายงานงบประมาณงานประชาสัมพันธ์กีฬา','สรุปการใช้งบประมาณด้านสื่อสาร เผยแพร่ และกิจกรรมประชาสัมพันธ์กีฬา','banknote',60,1),(7,'participation','รายงานการมีส่วนร่วมและการรับรู้ด้านกีฬา','สรุปจำนวนผู้เข้าร่วม การรับรู้ และหน่วยงานที่เกี่ยวข้องกับข่าวสารกีฬา','chart-no-axes-combined',70,1),(8,'issues','รายงานประเด็นสื่อสาร ปัญหา และข้อเสนอแนะด้านกีฬา','รวบรวมประเด็นปัญหา การสื่อสาร การแก้ไข และแนวทางพัฒนาประชาสัมพันธ์กีฬา','message-square-warning',80,1);
