INSERT INTO `report_templates` VALUES (1,1,'competition-summary','ร่างข่าวสรุปผลการแข่งขันกีฬา','สรุปผลการแข่งขันสำหรับใช้ประชาสัมพันธ์อย่างเป็นทางการ','[\"general\",\"performance\",\"sports_results\",\"outcomes\",\"problems\",\"attachments\"]',10,1),(2,1,'medal-summary','รายงานรางวัลและผลงานเด่นนักกีฬา','เรียบเรียงรางวัล อันดับ และผลงานเด่นสำหรับเผยแพร่','[\"general\",\"sports_results\",\"outcomes\",\"attachments\"]',20,1),(3,1,'sport-breakdown','รายงานผลการแข่งขันแยกตามชนิดกีฬา','จัดทำข้อมูลประชาสัมพันธ์จำแนกตามชนิดกีฬา','[\"general\",\"performance\",\"sports_results\",\"outcomes\"]',30,1),(4,1,'department-breakdown','รายงานผลงานกีฬาแยกตามหน่วยงาน','สรุปผลงานเพื่อสื่อสารภาพรวมรายหน่วยงานหรือสาขา','[\"general\",\"sports_results\",\"outcomes\"]',40,1),(5,2,'project-performance','รายงานประชาสัมพันธ์ผลโครงการกีฬา','รายงานการดำเนินโครงการกีฬาเพื่อเผยแพร่และเสนอผู้บริหาร','[\"general\",\"principles\",\"performance\",\"sports_results\",\"kpi\",\"budget\",\"outcomes\",\"problems\",\"attachments\"]',10,1),(6,2,'activity-performance','รายงานประชาสัมพันธ์กิจกรรมกีฬา','เรียบเรียงผลกิจกรรมกีฬา บรรยากาศ และประโยชน์ที่เกิดขึ้น','[\"general\",\"principles\",\"performance\",\"outcomes\",\"problems\",\"attachments\"]',20,1),(7,2,'project-plan','รายงานติดตามแผนประชาสัมพันธ์กีฬา','เปรียบเทียบแผนงานประชาสัมพันธ์กีฬากับผลการดำเนินงาน','[\"general\",\"principles\",\"performance\",\"kpi\",\"budget\",\"outcomes\",\"problems\"]',30,1),(8,3,'annual-performance','รายงานภาพรวมการประชาสัมพันธ์กีฬา','สรุปภาพรวมงานสื่อสาร ข่าวสาร และผลดำเนินงานด้านกีฬา','[\"general\",\"performance\",\"sports_results\",\"kpi\",\"budget\",\"outcomes\",\"problems\",\"attachments\"]',10,1),(9,4,'kpi-report','รายงาน KPI ประชาสัมพันธ์กีฬา','รายงานผลตัวชี้วัดด้านข่าวสารและการเผยแพร่กีฬา','[\"general\",\"performance\",\"kpi\",\"outcomes\",\"problems\"]',10,1),(10,4,'target-actual','รายงานเป้าหมายเทียบผลจริงงานสื่อสารกีฬา','เปรียบเทียบเป้าหมายกับผลจริงของงานประชาสัมพันธ์กีฬา','[\"general\",\"kpi\",\"outcomes\"]',20,1),(11,4,'achievement-report','รายงานความสำเร็จงานประชาสัมพันธ์กีฬา','สรุปร้อยละความสำเร็จและผลสัมฤทธิ์ของงานสื่อสารกีฬา','[\"general\",\"kpi\",\"outcomes\"]',30,1),(12,5,'executive-summary','สรุปผู้บริหารด้านประชาสัมพันธ์กีฬา','สรุปสาระสำคัญด้านประชาสัมพันธ์กีฬาอย่างเป็นทางการ','[\"general\",\"executive\",\"performance\",\"sports_results\",\"kpi\",\"budget\",\"outcomes\",\"problems\"]',10,1),(13,5,'annual-overview','รายงานประชาสัมพันธ์กีฬาประจำปี','สรุปภาพรวมข่าวสาร กิจกรรม และผลการแข่งขันประจำปี','[\"general\",\"executive\",\"performance\",\"sports_results\",\"kpi\",\"budget\",\"outcomes\",\"problems\"]',20,1),(14,5,'semester-overview','รายงานประชาสัมพันธ์กีฬาประจำภาคการศึกษา','สรุปงานประชาสัมพันธ์กีฬาในรอบภาคการศึกษา','[\"general\",\"executive\",\"performance\",\"sports_results\",\"kpi\",\"budget\",\"outcomes\",\"problems\"]',30,1),(15,6,'budget-summary','รายงานงบประมาณประชาสัมพันธ์กีฬา','สรุปการใช้งบประมาณเพื่อสื่อสารและเผยแพร่กิจกรรมกีฬา','[\"general\",\"budget\",\"outcomes\",\"problems\",\"attachments\"]',10,1),(16,7,'participation-summary','รายงานการมีส่วนร่วมจากข่าวสารกีฬา','สรุปการมีส่วนร่วม การรับรู้ และกลุ่มเป้าหมายของประชาสัมพันธ์กีฬา','[\"general\",\"performance\",\"outcomes\"]',10,1),(17,8,'issues-summary','รายงานประเด็นสื่อสารและข้อเสนอแนะกีฬา','สรุปปัญหาการสื่อสารกีฬาและแนวทางปรับปรุง','[\"general\",\"problems\",\"attachments\"]',10,1);
