--
-- Table structure for table `reports`
--

DROP TABLE IF EXISTS `reports`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `reports` (
  `id` int(11) NOT NULL,
  `title` varchar(255) NOT NULL,
  `category_id` int(11) NOT NULL,
  `template_id` int(11) NOT NULL,
  `tournament_id` int(11) DEFAULT NULL,
  `academic_year` varchar(20) DEFAULT NULL,
  `fiscal_year` varchar(20) DEFAULT NULL,
  `semester` varchar(30) DEFAULT NULL,
  `start_date` varchar(30) DEFAULT NULL,
  `end_date` varchar(30) DEFAULT NULL,
  `department` varchar(190) DEFAULT NULL,
  `responsible_person` varchar(190) DEFAULT NULL,
  `prepared_by` varchar(190) DEFAULT NULL,
  `report_date` varchar(30) DEFAULT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'draft',
  `general_json` mediumtext DEFAULT NULL,
  `performance_json` mediumtext DEFAULT NULL,
  `outcomes_json` mediumtext DEFAULT NULL,
  `problems_json` mediumtext DEFAULT NULL,
  `executive_summary` mediumtext DEFAULT NULL,
  `created_by` varchar(190) DEFAULT NULL,
  `published_at` varchar(30) DEFAULT NULL,
  `created_at` varchar(30) DEFAULT NULL,
  `updated_at` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_reports_template` (`template_id`),
  KEY `idx_reports_status_year` (`status`,`academic_year`),
  KEY `idx_reports_category_template` (`category_id`,`template_id`),
  KEY `idx_reports_tournament` (`tournament_id`),
  CONSTRAINT `fk_reports_category` FOREIGN KEY (`category_id`) REFERENCES `report_categories` (`id`),
  CONSTRAINT `fk_reports_template` FOREIGN KEY (`template_id`) REFERENCES `report_templates` (`id`),
  CONSTRAINT `fk_reports_tournament` FOREIGN KEY (`tournament_id`) REFERENCES `tournaments` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

