/*!40000 ALTER TABLE `reports` DISABLE KEYS */;
INSERT INTO `reports` VALUES (1,'รายงานผลการแข่งขันฟุตบอลและภาพรวมทุกกีฬา (37380)',2,5,1,'2569','2570','1','2026-10-12','2026-10-16','คณะครุศาสตร์อุตสาหกรรม','งานกิจการนักศึกษาและคณะกรรมการกีฬา','ผู้ดูแลระบบทดสอบ','2026-10-05','published','{\"project_name\":\"โครงการกีฬาสี RMUTT Sport Demo 2569\",\"competition_name\":\"กีฬาสี RMUTT Sport Demo 2569 - ทุกกีฬา (37380)\",\"operation_date\":\"2026-10-12\",\"location\":\"สนามกีฬากลาง มทร.ธัญบุรี\",\"rationale\":\"เพื่อจำลองการใช้งานระบบจัดการแข่งขันกีฬาจากต้นทางถึงการรายงานผลและเผยแพร่ข่าว\",\"objectives\":\"1. ทดสอบ workflow ทัวร์นาเมนต์ครบทุกขั้น\\n2. แสดงหน้าตาเว็บเมื่อมีข้อมูลจริงครบทุกเมนู\\n3. จัดทำรายงานผลการแข่งขันให้ผู้บริหารตรวจสอบได้\",\"target_group\":\"นักศึกษา บุคลากร เจ้าหน้าที่กีฬา และผู้บริหารคณะ\"}','{\"operation_detail\":\"ตั้งค่าทัวร์นาเมนต์ 9 กีฬา สร้างทีม 18 ทีม บันทึกนักกีฬา 78 คน และบันทึกผลการแข่งขัน 9 รายการ\"}','{\"performance_result\":\"ฟุตบอลรอบชิงชนะเลิศ: ฟุตบอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 3-1 ฟุตบอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B. กีฬาอื่นมีผลการแข่งขันตัวอย่างครบทุกชนิด\",\"benefits\":\"ระบบสามารถแสดงผลบนหน้าเว็บสาธารณะ แดชบอร์ด ศูนย์แข่งขัน ตารางคะแนน ข่าว และรายงานได้ต่อเนื่อง\",\"participant_impact\":\"ผู้ใช้งานเห็นภาพรวมการจัดการแข่งขันตั้งแต่ข้อมูลกีฬา นักกีฬา ทีม ตารางแข่ง ผล ข่าว และรายงานในระบบเดียว\"}','{\"obstacles\":\"ข้อมูลนี้เป็นชุดจำลองสำหรับทดสอบหน้าตาเว็บ ยังไม่ใช่ผลการแข่งขันจริง\",\"solutions\":\"เมื่อใช้งานจริงให้เจ้าหน้าที่แทนที่ข้อมูลจำลองด้วยข้อมูลจากการแข่งขันจริงและตรวจสอบรายชื่อก่อนเผยแพร่\",\"recommendations\":\"ควรใช้ชุดข้อมูลนี้เป็นต้นแบบในการฝึกกรอกข้อมูลและตรวจ flow ก่อนนำระบบขึ้นใช้งานจริง\"}','ทัวร์นาเมนต์จำลองถูกสร้างครบทุกชนิดกีฬา โดยเน้นฟุตบอลเป็นรายการหลัก มีการตั้งค่ากติกา ทีม นักกีฬา ตารางแข่งขัน ผลการแข่งขัน ข่าวประชาสัมพันธ์ และรายงานครบถ้วน','admin@rmutt.local','2026-10-05 18:37:27','2026-10-05 18:37:27','2026-10-05 18:37:27'),(2,'รายงานติดตามแผนประชาสัมพันธ์กีฬา',2,7,NULL,'69','','',NULL,NULL,'','','ผู้ดูแลระบบ','2026-10-08','draft','{\"project_name\":\"รายงานติดตามแผนประชาสัมพันธ์กีฬา\",\"competition_name\":\"\",\"operation_date\":\"\",\"location\":\"\",\"rationale\":\"งานประชาสัมพันธ์ด้านกีฬาจัดทำขึ้นเพื่อรวบรวมและเผยแพร่ข้อมูลการแข่งขัน กิจกรรม ผลงานนักกีฬา และภาพรวมการมีส่วนร่วมของหน่วยงานที่เกี่ยวข้อง ให้มีความถูกต้อง เป็นระบบ และเหมาะสมต่อการสื่อสารภายในและภายนอกมหาวิทยาลัย\",\"objectives\":\"1. เพื่อสรุปข้อมูลรายงานประชาสัมพันธ์โครงการ/กิจกรรมกีฬาให้เป็นเอกสารทางการ\\n2. เพื่อใช้ประกอบการเผยแพร่ข่าวสารกีฬาและการรายงานต่อผู้บริหาร\\n3. เพื่อสนับสนุนการติดตามผลการแข่งขันและการพัฒนางานประชาสัมพันธ์กีฬา\",\"target_group\":\"ผู้บริหาร คณะกรรมการดำเนินงานกีฬา เจ้าหน้าที่ประชาสัมพันธ์ ผู้ควบคุมทีม นักกีฬา นักศึกษา และผู้มีส่วนเกี่ยวข้อง\"}','{\"operation_detail\":\"การดำเนินงานรายงานประชาสัมพันธ์โครงการ/กิจกรรมกีฬา ดำเนินการโดยรวบรวมข้อมูลจากระบบจัดการกีฬา ตรวจสอบรายการแข่งขัน ทีม นักกีฬา และผลการแข่งขันที่เกี่ยวข้อง จากนั้นเรียบเรียงเป็นรายงานประชาสัมพันธ์ในรูปแบบทางการ โดยมีข้อมูลทีมเข้าร่วม 18 ทีม นักกีฬา 78 คน และรายการแข่งขัน 9 รายการ ครอบคลุมกีฬา ฟุตบอล, วอลเลย์บอล, วิ่ง 100 เมตร, ฟุตซอล, บาสเกตบอล, แบดมินตัน, เทเบิลเทนนิส และเปตอง จากหน่วยงาน/สาขา สาขาวิชาวิศวกรรมคอมพิวเตอร์ และสาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ และมีการแข่งขันที่บันทึกผลแล้ว 9 รายการ\"}','{\"performance_result\":\"ผลการแข่งขันที่บันทึกในระบบ ได้แก่ ฟุตบอล: ฟุตบอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 3 - 1 ฟุตบอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | วอลเลย์บอล: วอลเลย์บอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 2 - 1 วอลเลย์บอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | วิ่ง 100 เมตร: วิ่ง 100 เมตร สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 2 - 0 วิ่ง 100 เมตร สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | ฟุตซอล: ฟุตซอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 2 - 1 ฟุตซอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | บาสเกตบอล: บาสเกตบอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 3 - 1 บาสเกตบอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | แบดมินตัน: แบดมินตัน สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 2 - 0 แบดมินตัน สาขาวิชาวิศวกรรมคอมพิวเตอร์ B\",\"benefits\":\"หน่วยงานสามารถนำข้อมูลไปใช้ประกอบการเผยแพร่ข่าวสาร สรุปผลการดำเนินงาน จัดทำเอกสารเสนอผู้บริหาร และเก็บเป็นหลักฐานอ้างอิงสำหรับการจัดกิจกรรมกีฬาครั้งต่อไป\",\"participant_impact\":\"ผู้เข้าร่วมและนักกีฬาได้รับการนำเสนอผลงานอย่างเป็นระบบ ช่วยสร้างการรับรู้ ความภาคภูมิใจ และส่งเสริมภาพลักษณ์ที่ดีของกิจกรรมกีฬาของมหาวิทยาลัย\"}','{\"obstacles\":\"ข้อมูลบางส่วนอาจยังไม่สมบูรณ์ เช่น ผลการแข่งขัน รายชื่อทีม หรือรายละเอียดผู้เข้าร่วม จึงจำเป็นต้องตรวจสอบกับผู้รับผิดชอบก่อนเผยแพร่\",\"solutions\":\"กำหนดผู้รับผิดชอบตรวจทานข้อมูลแต่ละส่วน และบันทึกผลการแข่งขันให้ครบถ้วนก่อนจัดทำรายงานฉบับสมบูรณ์\",\"recommendations\":\"ควรจัดทำแนวทางการบันทึกข้อมูลและรอบเวลาการส่งข้อมูลประชาสัมพันธ์กีฬา เพื่อให้รายงานมีความถูกต้อง ทันเวลา และนำไปใช้เผยแพร่ได้อย่างต่อเนื่อง\"}','รายงานติดตามแผนประชาสัมพันธ์กีฬาฉบับนี้จัดทำขึ้นเพื่อสรุปสาระสำคัญของงานประชาสัมพันธ์ด้านกีฬา โดยมีข้อมูลทีมเข้าร่วม 18 ทีม นักกีฬา 78 คน และรายการแข่งขัน 9 รายการ ครอบคลุมกีฬา ฟุตบอล, วอลเลย์บอล, วิ่ง 100 เมตร, ฟุตซอล, บาสเกตบอล, แบดมินตัน, เทเบิลเทนนิส และเปตอง จากหน่วยงาน/สาขา สาขาวิชาวิศวกรรมคอมพิวเตอร์ และสาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ มีผลการแข่งขันที่บันทึกแล้ว 9 รายการ ข้อมูลดังกล่าวสามารถใช้ประกอบการเผยแพร่ข่าวสาร การรายงานผลต่อผู้บริหาร และการพัฒนาการดำเนินงานประชาสัมพันธ์กีฬาให้มีความเป็นระบบยิ่งขึ้น','admin@rmutt.local',NULL,'2026-10-08 21:10:49','2026-10-08 21:10:49'),(3,'รายงานสรุปผลการดำเนินงานด้านกีฬา ประจำปีการศึกษา 69',5,13,NULL,'69','','',NULL,NULL,'','','ผู้ดูแลระบบ','2026-10-08','draft','{\"project_name\":\"รายงานสรุปผลการดำเนินงานด้านกีฬา ประจำปีการศึกษา 69\",\"competition_name\":\"\",\"operation_date\":\"\",\"location\":\"\",\"rationale\":\"งานประชาสัมพันธ์ด้านกีฬาจัดทำขึ้นเพื่อรวบรวมและเผยแพร่ข้อมูลการแข่งขัน กิจกรรม ผลงานนักกีฬา และภาพรวมการมีส่วนร่วมของหน่วยงานที่เกี่ยวข้อง ให้มีความถูกต้อง เป็นระบบ และเหมาะสมต่อการสื่อสารภายในและภายนอกมหาวิทยาลัย\",\"objectives\":\"1. เพื่อสรุปข้อมูลรายงานสรุปประชาสัมพันธ์กีฬาสำหรับผู้บริหารให้เป็นเอกสารทางการ\\n2. เพื่อใช้ประกอบการเผยแพร่ข่าวสารกีฬาและการรายงานต่อผู้บริหาร\\n3. เพื่อสนับสนุนการติดตามผลการแข่งขันและการพัฒนางานประชาสัมพันธ์กีฬา\",\"target_group\":\"ผู้บริหาร คณะกรรมการดำเนินงานกีฬา เจ้าหน้าที่ประชาสัมพันธ์ ผู้ควบคุมทีม นักกีฬา นักศึกษา และผู้มีส่วนเกี่ยวข้อง\"}','{\"operation_detail\":\"การดำเนินงานรายงานสรุปประชาสัมพันธ์กีฬาสำหรับผู้บริหาร ดำเนินการโดยรวบรวมข้อมูลจากระบบจัดการกีฬา ตรวจสอบรายการแข่งขัน ทีม นักกีฬา และผลการแข่งขันที่เกี่ยวข้อง จากนั้นเรียบเรียงเป็นรายงานประชาสัมพันธ์ในรูปแบบทางการ โดยมีข้อมูลทีมเข้าร่วม 18 ทีม นักกีฬา 78 คน และรายการแข่งขัน 9 รายการ ครอบคลุมกีฬา ฟุตบอล, วอลเลย์บอล, วิ่ง 100 เมตร, ฟุตซอล, บาสเกตบอล, แบดมินตัน, เทเบิลเทนนิส และเปตอง จากหน่วยงาน/สาขา สาขาวิชาวิศวกรรมคอมพิวเตอร์ และสาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ และมีการแข่งขันที่บันทึกผลแล้ว 9 รายการ\"}','{\"performance_result\":\"ผลการแข่งขันที่บันทึกในระบบ ได้แก่ ฟุตบอล: ฟุตบอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 3 - 1 ฟุตบอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | วอลเลย์บอล: วอลเลย์บอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 2 - 1 วอลเลย์บอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | วิ่ง 100 เมตร: วิ่ง 100 เมตร สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 2 - 0 วิ่ง 100 เมตร สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | ฟุตซอล: ฟุตซอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 2 - 1 ฟุตซอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | บาสเกตบอล: บาสเกตบอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 3 - 1 บาสเกตบอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | แบดมินตัน: แบดมินตัน สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 2 - 0 แบดมินตัน สาขาวิชาวิศวกรรมคอมพิวเตอร์ B\",\"benefits\":\"หน่วยงานสามารถนำข้อมูลไปใช้ประกอบการเผยแพร่ข่าวสาร สรุปผลการดำเนินงาน จัดทำเอกสารเสนอผู้บริหาร และเก็บเป็นหลักฐานอ้างอิงสำหรับการจัดกิจกรรมกีฬาครั้งต่อไป\",\"participant_impact\":\"ผู้เข้าร่วมและนักกีฬาได้รับการนำเสนอผลงานอย่างเป็นระบบ ช่วยสร้างการรับรู้ ความภาคภูมิใจ และส่งเสริมภาพลักษณ์ที่ดีของกิจกรรมกีฬาของมหาวิทยาลัย\"}','{\"obstacles\":\"ข้อมูลบางส่วนอาจยังไม่สมบูรณ์ เช่น ผลการแข่งขัน รายชื่อทีม หรือรายละเอียดผู้เข้าร่วม จึงจำเป็นต้องตรวจสอบกับผู้รับผิดชอบก่อนเผยแพร่\",\"solutions\":\"กำหนดผู้รับผิดชอบตรวจทานข้อมูลแต่ละส่วน และบันทึกผลการแข่งขันให้ครบถ้วนก่อนจัดทำรายงานฉบับสมบูรณ์\",\"recommendations\":\"ควรจัดทำแนวทางการบันทึกข้อมูลและรอบเวลาการส่งข้อมูลประชาสัมพันธ์กีฬา เพื่อให้รายงานมีความถูกต้อง ทันเวลา และนำไปใช้เผยแพร่ได้อย่างต่อเนื่อง\"}','รายงานประชาสัมพันธ์กีฬาประจำปีฉบับนี้จัดทำขึ้นเพื่อสรุปสาระสำคัญของงานประชาสัมพันธ์ด้านกีฬา โดยมีข้อมูลทีมเข้าร่วม 18 ทีม นักกีฬา 78 คน และรายการแข่งขัน 9 รายการ ครอบคลุมกีฬา ฟุตบอล, วอลเลย์บอล, วิ่ง 100 เมตร, ฟุตซอล, บาสเกตบอล, แบดมินตัน, เทเบิลเทนนิส และเปตอง จากหน่วยงาน/สาขา สาขาวิชาวิศวกรรมคอมพิวเตอร์ และสาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ มีผลการแข่งขันที่บันทึกแล้ว 9 รายการ ข้อมูลดังกล่าวสามารถใช้ประกอบการเผยแพร่ข่าวสาร การรายงานผลต่อผู้บริหาร และการพัฒนาการดำเนินงานประชาสัมพันธ์กีฬาให้มีความเป็นระบบยิ่งขึ้น','admin@rmutt.local',NULL,'2026-10-08 21:31:22','2026-10-08 21:31:22'),(4,'รายงานสรุปผลการดำเนินงานด้านกีฬา ประจำปีการศึกษา 69',5,13,NULL,'69','','',NULL,NULL,'','','ผู้ดูแลระบบ','2026-10-08','draft','{\"project_name\":\"รายงานสรุปผลการดำเนินงานด้านกีฬา ประจำปีการศึกษา 69\",\"competition_name\":\"\",\"operation_date\":\"\",\"location\":\"\",\"rationale\":\"งานประชาสัมพันธ์ด้านกีฬาจัดทำขึ้นเพื่อรวบรวมและเผยแพร่ข้อมูลการแข่งขัน กิจกรรม ผลงานนักกีฬา และภาพรวมการมีส่วนร่วมของหน่วยงานที่เกี่ยวข้อง ให้มีความถูกต้อง เป็นระบบ และเหมาะสมต่อการสื่อสารภายในและภายนอกมหาวิทยาลัย\",\"objectives\":\"1. เพื่อสรุปข้อมูลรายงานสรุปประชาสัมพันธ์กีฬาสำหรับผู้บริหารให้เป็นเอกสารทางการ\\n2. เพื่อใช้ประกอบการเผยแพร่ข่าวสารกีฬาและการรายงานต่อผู้บริหาร\\n3. เพื่อสนับสนุนการติดตามผลการแข่งขันและการพัฒนางานประชาสัมพันธ์กีฬา\",\"target_group\":\"ผู้บริหาร คณะกรรมการดำเนินงานกีฬา เจ้าหน้าที่ประชาสัมพันธ์ ผู้ควบคุมทีม นักกีฬา นักศึกษา และผู้มีส่วนเกี่ยวข้อง\"}','{\"operation_detail\":\"การดำเนินงานรายงานสรุปประชาสัมพันธ์กีฬาสำหรับผู้บริหาร ดำเนินการโดยรวบรวมข้อมูลจากระบบจัดการกีฬา ตรวจสอบรายการแข่งขัน ทีม นักกีฬา และผลการแข่งขันที่เกี่ยวข้อง จากนั้นเรียบเรียงเป็นรายงานประชาสัมพันธ์ในรูปแบบทางการ โดยมีข้อมูลทีมเข้าร่วม 18 ทีม นักกีฬา 78 คน และรายการแข่งขัน 9 รายการ ครอบคลุมกีฬา ฟุตบอล, วอลเลย์บอล, วิ่ง 100 เมตร, ฟุตซอล, บาสเกตบอล, แบดมินตัน, เทเบิลเทนนิส และเปตอง จากหน่วยงาน/สาขา สาขาวิชาวิศวกรรมคอมพิวเตอร์ และสาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ และมีการแข่งขันที่บันทึกผลแล้ว 9 รายการ\"}','{\"performance_result\":\"ผลการแข่งขันที่บันทึกในระบบ ได้แก่ ฟุตบอล: ฟุตบอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 3 - 1 ฟุตบอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | วอลเลย์บอล: วอลเลย์บอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 2 - 1 วอลเลย์บอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | วิ่ง 100 เมตร: วิ่ง 100 เมตร สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 2 - 0 วิ่ง 100 เมตร สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | ฟุตซอล: ฟุตซอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 2 - 1 ฟุตซอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | บาสเกตบอล: บาสเกตบอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 3 - 1 บาสเกตบอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | แบดมินตัน: แบดมินตัน สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 2 - 0 แบดมินตัน สาขาวิชาวิศวกรรมคอมพิวเตอร์ B\",\"benefits\":\"หน่วยงานสามารถนำข้อมูลไปใช้ประกอบการเผยแพร่ข่าวสาร สรุปผลการดำเนินงาน จัดทำเอกสารเสนอผู้บริหาร และเก็บเป็นหลักฐานอ้างอิงสำหรับการจัดกิจกรรมกีฬาครั้งต่อไป\",\"participant_impact\":\"ผู้เข้าร่วมและนักกีฬาได้รับการนำเสนอผลงานอย่างเป็นระบบ ช่วยสร้างการรับรู้ ความภาคภูมิใจ และส่งเสริมภาพลักษณ์ที่ดีของกิจกรรมกีฬาของมหาวิทยาลัย\"}','{\"obstacles\":\"ข้อมูลบางส่วนอาจยังไม่สมบูรณ์ เช่น ผลการแข่งขัน รายชื่อทีม หรือรายละเอียดผู้เข้าร่วม จึงจำเป็นต้องตรวจสอบกับผู้รับผิดชอบก่อนเผยแพร่\",\"solutions\":\"กำหนดผู้รับผิดชอบตรวจทานข้อมูลแต่ละส่วน และบันทึกผลการแข่งขันให้ครบถ้วนก่อนจัดทำรายงานฉบับสมบูรณ์\",\"recommendations\":\"ควรจัดทำแนวทางการบันทึกข้อมูลและรอบเวลาการส่งข้อมูลประชาสัมพันธ์กีฬา เพื่อให้รายงานมีความถูกต้อง ทันเวลา และนำไปใช้เผยแพร่ได้อย่างต่อเนื่อง\"}','รายงานประชาสัมพันธ์กีฬาประจำปีฉบับนี้จัดทำขึ้นเพื่อสรุปสาระสำคัญของงานประชาสัมพันธ์ด้านกีฬา โดยมีข้อมูลทีมเข้าร่วม 18 ทีม นักกีฬา 78 คน และรายการแข่งขัน 9 รายการ ครอบคลุมกีฬา ฟุตบอล, วอลเลย์บอล, วิ่ง 100 เมตร, ฟุตซอล, บาสเกตบอล, แบดมินตัน, เทเบิลเทนนิส และเปตอง จากหน่วยงาน/สาขา สาขาวิชาวิศวกรรมคอมพิวเตอร์ และสาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ มีผลการแข่งขันที่บันทึกแล้ว 9 รายการ ข้อมูลดังกล่าวสามารถใช้ประกอบการเผยแพร่ข่าวสาร การรายงานผลต่อผู้บริหาร และการพัฒนาการดำเนินงานประชาสัมพันธ์กีฬาให้มีความเป็นระบบยิ่งขึ้น','admin@rmutt.local',NULL,'2026-10-08 21:41:39','2026-10-08 21:41:53'),(5,'รายงานสรุปผลการดำเนินงานด้านกีฬา ประจำปีการศึกษา 69',5,13,NULL,'69','','',NULL,NULL,'','','ผู้ดูแลระบบ','2026-10-08','draft','{\"project_name\":\"รายงานสรุปผลการดำเนินงานด้านกีฬา ประจำปีการศึกษา 69\",\"competition_name\":\"\",\"operation_date\":\"\",\"location\":\"\",\"rationale\":\"งานประชาสัมพันธ์ด้านกีฬาจัดทำขึ้นเพื่อรวบรวมและเผยแพร่ข้อมูลการแข่งขัน กิจกรรม ผลงานนักกีฬา และภาพรวมการมีส่วนร่วมของหน่วยงานที่เกี่ยวข้อง ให้มีความถูกต้อง เป็นระบบ และเหมาะสมต่อการสื่อสารภายในและภายนอกมหาวิทยาลัย\",\"objectives\":\"1. เพื่อสรุปข้อมูลรายงานสรุปประชาสัมพันธ์กีฬาสำหรับผู้บริหารให้เป็นเอกสารทางการ\\n2. เพื่อใช้ประกอบการเผยแพร่ข่าวสารกีฬาและการรายงานต่อผู้บริหาร\\n3. เพื่อสนับสนุนการติดตามผลการแข่งขันและการพัฒนางานประชาสัมพันธ์กีฬา\",\"target_group\":\"ผู้บริหาร คณะกรรมการดำเนินงานกีฬา เจ้าหน้าที่ประชาสัมพันธ์ ผู้ควบคุมทีม นักกีฬา นักศึกษา และผู้มีส่วนเกี่ยวข้อง\"}','{\"operation_detail\":\"การดำเนินงานรายงานสรุปประชาสัมพันธ์กีฬาสำหรับผู้บริหาร ดำเนินการโดยรวบรวมข้อมูลจากระบบจัดการกีฬา ตรวจสอบรายการแข่งขัน ทีม นักกีฬา และผลการแข่งขันที่เกี่ยวข้อง จากนั้นเรียบเรียงเป็นรายงานประชาสัมพันธ์ในรูปแบบทางการ โดยมีข้อมูลทีมเข้าร่วม 18 ทีม นักกีฬา 78 คน และรายการแข่งขัน 9 รายการ ครอบคลุมกีฬา ฟุตบอล, วอลเลย์บอล, วิ่ง 100 เมตร, ฟุตซอล, บาสเกตบอล, แบดมินตัน, เทเบิลเทนนิส และเปตอง จากหน่วยงาน/สาขา สาขาวิชาวิศวกรรมคอมพิวเตอร์ และสาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ และมีการแข่งขันที่บันทึกผลแล้ว 9 รายการ\"}','{\"performance_result\":\"ผลการแข่งขันที่บันทึกในระบบ ได้แก่ ฟุตบอล: ฟุตบอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 3 - 1 ฟุตบอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | วอลเลย์บอล: วอลเลย์บอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 2 - 1 วอลเลย์บอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | วิ่ง 100 เมตร: วิ่ง 100 เมตร สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 2 - 0 วิ่ง 100 เมตร สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | ฟุตซอล: ฟุตซอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 2 - 1 ฟุตซอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | บาสเกตบอล: บาสเกตบอล สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 3 - 1 บาสเกตบอล สาขาวิชาวิศวกรรมคอมพิวเตอร์ B | แบดมินตัน: แบดมินตัน สาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ A 2 - 0 แบดมินตัน สาขาวิชาวิศวกรรมคอมพิวเตอร์ B\",\"benefits\":\"หน่วยงานสามารถนำข้อมูลไปใช้ประกอบการเผยแพร่ข่าวสาร สรุปผลการดำเนินงาน จัดทำเอกสารเสนอผู้บริหาร และเก็บเป็นหลักฐานอ้างอิงสำหรับการจัดกิจกรรมกีฬาครั้งต่อไป\",\"participant_impact\":\"ผู้เข้าร่วมและนักกีฬาได้รับการนำเสนอผลงานอย่างเป็นระบบ ช่วยสร้างการรับรู้ ความภาคภูมิใจ และส่งเสริมภาพลักษณ์ที่ดีของกิจกรรมกีฬาของมหาวิทยาลัย\"}','{\"obstacles\":\"ข้อมูลบางส่วนอาจยังไม่สมบูรณ์ เช่น ผลการแข่งขัน รายชื่อทีม หรือรายละเอียดผู้เข้าร่วม จึงจำเป็นต้องตรวจสอบกับผู้รับผิดชอบก่อนเผยแพร่\",\"solutions\":\"กำหนดผู้รับผิดชอบตรวจทานข้อมูลแต่ละส่วน และบันทึกผลการแข่งขันให้ครบถ้วนก่อนจัดทำรายงานฉบับสมบูรณ์\",\"recommendations\":\"ควรจัดทำแนวทางการบันทึกข้อมูลและรอบเวลาการส่งข้อมูลประชาสัมพันธ์กีฬา เพื่อให้รายงานมีความถูกต้อง ทันเวลา และนำไปใช้เผยแพร่ได้อย่างต่อเนื่อง\"}','รายงานประชาสัมพันธ์กีฬาประจำปีฉบับนี้จัดทำขึ้นเพื่อสรุปสาระสำคัญของงานประชาสัมพันธ์ด้านกีฬา โดยมีข้อมูลทีมเข้าร่วม 18 ทีม นักกีฬา 78 คน และรายการแข่งขัน 9 รายการ ครอบคลุมกีฬา ฟุตบอล, วอลเลย์บอล, วิ่ง 100 เมตร, ฟุตซอล, บาสเกตบอล, แบดมินตัน, เทเบิลเทนนิส และเปตอง จากหน่วยงาน/สาขา สาขาวิชาวิศวกรรมคอมพิวเตอร์ และสาขาวิชานวัตกรรมการเรียนรู้และเทคโนโลยีสารสนเทศ มีผลการแข่งขันที่บันทึกแล้ว 9 รายการ ข้อมูลดังกล่าวสามารถใช้ประกอบการเผยแพร่ข่าวสาร การรายงานผลต่อผู้บริหาร และการพัฒนาการดำเนินงานประชาสัมพันธ์กีฬาให้มีความเป็นระบบยิ่งขึ้น','admin@rmutt.local',NULL,'2026-10-08 22:06:45','2026-10-08 22:06:45');
