--
-- Table structure for table `tasks`
--

DROP TABLE IF EXISTS `tasks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tasks` (
  `id` int(11) NOT NULL,
  `title` varchar(190) NOT NULL,
  `description` text DEFAULT NULL,
  `category` varchar(50) NOT NULL DEFAULT 'general',
  `priority` varchar(50) NOT NULL DEFAULT 'normal',
  `status` varchar(50) NOT NULL DEFAULT 'todo',
  `due_at` varchar(30) DEFAULT NULL,
  `related_type` varchar(100) DEFAULT NULL,
  `related_id` varchar(100) DEFAULT NULL,
  `assignee_email` varchar(190) DEFAULT NULL,
  `created_by` varchar(190) DEFAULT NULL,
  `completed_at` varchar(30) DEFAULT NULL,
  `created_at` varchar(30) DEFAULT NULL,
  `updated_at` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_tasks_status_due` (`status`,`due_at`),
  KEY `idx_tasks_assignee` (`assignee_email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

